// Conversion throughput: uploads a batch of Full HD PNG to JPEG jobs one after another, then waits
// until every one has finished. Reports how long the uploads took and how many jobs were converted
// per minute, timed from the first upload (workers start while the rest are still being sent).
// The image (/fixtures/photo.png) is generated by loadtests/run.ps1.
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Trend } from 'k6/metrics';

const baseUrl = __ENV.BASE_URL || 'http://localhost:5081';
const apiKey = __ENV.API_KEY || 'cvt_devlocal_DevelopmentOnlyKeyDoNotUseInProd';
const batch = Number(__ENV.JOBS || 300);
const photo = open('/fixtures/photo.png', 'b');
const headers = { 'X-Api-Key': apiKey };

const jobsPerMinute = new Trend('convertapi_jobs_per_minute');
const uploadSeconds = new Trend('convertapi_upload_seconds');
const failedJobs = new Counter('convertapi_failed_jobs');
const unfinishedJobs = new Counter('convertapi_unfinished_jobs');

export const options = {
  scenarios: {
    throughput: { executor: 'shared-iterations', vus: 1, iterations: 1, maxDuration: '30m' },
  },
  // A run only counts if every upload was accepted and every job succeeded in time.
  thresholds: {
    checks: ['rate==1'],
    convertapi_failed_jobs: ['count==0'],
    convertapi_unfinished_jobs: ['count==0'],
  },
};

/** The job's status, or null when the answer is not a job (an error page, a 429). */
function statusOf(id) {
  const response = http.get(`${baseUrl}/v1/jobs/${id}`, { headers, tags: { name: 'job status' } });
  return response.status === 200 ? response.json('status') : null;
}

export default function () {
  const started = Date.now();
  const ids = [];
  for (let i = 0; i < batch; i++) {
    const response = http.post(
      `${baseUrl}/v1/jobs`,
      { file: http.file(photo, 'photo.png', 'image/png'), targetFormat: 'jpg' },
      { headers, tags: { name: 'create job' } },
    );
    if (check(response, { 'accepted (202)': (r) => r.status === 202 })) {
      ids.push(response.json('id'));
    }
  }
  const uploaded = (Date.now() - started) / 1000;
  uploadSeconds.add(uploaded);

  const pending = new Set(ids);
  while (pending.size > 0 && Date.now() - started < 25 * 60 * 1000) {
    for (const id of [...pending]) {
      const status = statusOf(id);
      if (status === 'Succeeded') {
        pending.delete(id);
      } else if (status === 'Failed' || status === 'Canceled') {
        pending.delete(id);
        failedJobs.add(1);
      }
    }
    if (pending.size > 0) {
      sleep(0.1);
    }
  }
  unfinishedJobs.add(pending.size);

  const seconds = (Date.now() - started) / 1000;
  jobsPerMinute.add(((ids.length - pending.size) * 60) / seconds);
  console.log(
    `${ids.length - pending.size} of ${ids.length} jobs finished in ${seconds.toFixed(1)} s (uploads took ${uploaded.toFixed(1)} s)`,
  );
}
